int maxKilledEnemies(char**g,int m,int*cols){if(!m)return 0;int n=cols[0],*cc=calloc(n,sizeof(int)),best=0,row=0;for(int i=0;i<m;i++)for(int j=0;j<n;j++){if(j==0||g[i][j-1]=='W'){row=0;for(int k=j;k<n&&g[i][k]!='W';k++)if(g[i][k]=='E')row++;}if(i==0||g[i-1][j]=='W'){cc[j]=0;for(int k=i;k<m&&g[k][j]!='W';k++)if(g[k][j]=='E')cc[j]++;}if(g[i][j]=='0'&&row+cc[j]>best)best=row+cc[j];}free(cc);return best;}
